CREATE FUNCTION public.admin_customer_costs(p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, generations bigint, trial_generations bigint, total_usd numeric, trial_usd numeric) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH costs AS (SELECT c.user_id,g.trial,CASE WHEN c.kind='ia' THEN (c.input_tokens*coalesce((s.prices->'modelos'->c.model->>'entrada')::numeric,0)+c.output_tokens*coalesce((s.prices->'modelos'->c.model->>'saida')::numeric,0))/1000000 WHEN c.kind='transcricao' THEN c.units*coalesce((s.prices->>'transcricaoMin')::numeric,0) ELSE 0 END AS usd FROM public.usage_costs c LEFT JOIN public.generations g ON g.id=c.generation_id CROSS JOIN public.app_settings s WHERE s.id=true) SELECT p.id,(SELECT count(*) FROM public.generations g WHERE g.user_id=p.id),(SELECT count(*) FROM public.generations g WHERE g.user_id=p.id AND g.trial),coalesce(sum(c.usd),0),coalesce(sum(c.usd) FILTER(WHERE c.trial),0) FROM public.profiles p LEFT JOIN costs c ON c.user_id=p.id WHERE public.has_role(auth.uid(),'admin') GROUP BY p.id,p.created_at ORDER BY p.created_at DESC OFFSET greatest(0,p_offset) LIMIT 25 $$;
REVOKE ALL ON FUNCTION public.admin_customer_costs(integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_customer_costs(integer) TO authenticated,service_role;
CREATE FUNCTION public.admin_cost_totals() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('total_usd',coalesce(sum(CASE WHEN c.kind='ia' THEN (c.input_tokens*coalesce((s.prices->'modelos'->c.model->>'entrada')::numeric,0)+c.output_tokens*coalesce((s.prices->'modelos'->c.model->>'saida')::numeric,0))/1000000 WHEN c.kind='transcricao' THEN c.units*coalesce((s.prices->>'transcricaoMin')::numeric,0) ELSE 0 END),0)) FROM public.usage_costs c CROSS JOIN public.app_settings s WHERE s.id=true AND public.has_role(auth.uid(),'admin') $$;
REVOKE ALL ON FUNCTION public.admin_cost_totals() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_cost_totals() TO authenticated,service_role;